def groupStrings(words):
    # Convert each word to a 26-bit mask
    mask_to_index = {}
    n = len(words)
    for idx, word in enumerate(words):
        mask = 0
        for c in word:
            mask |= (1 << (ord(c) - ord('a')))
        mask_to_index[mask] = idx  # only need index, since duplicates are not allowed

    parent = [i for i in range(n)]  # Union Find: parent[i] = i initially
    size = [1] * n  # sizes of groups

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path compression
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if size[rx] < size[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        size[rx] += size[ry]

    for idx, word in enumerate(words):
        cur_mask = 0
        for c in word:
            cur_mask |= (1 << (ord(c) - ord('a')))
        # Remove one letter
        for i in range(26):
            if cur_mask & (1 << i):
                neigh = cur_mask ^ (1 << i)
                if neigh in mask_to_index:
                    union(idx, mask_to_index[neigh])
        # Replace one letter
        for i in range(26):
            if cur_mask & (1 << i):
                for j in range(26):
                    if not (cur_mask & (1 << j)):
                        neigh = cur_mask ^ (1 << i) | (1 << j)
                        if neigh in mask_to_index:
                            union(idx, mask_to_index[neigh])

    # Count groups and size of largest group
    from collections import Counter
    count = Counter()
    for i in range(n):
        root = find(i)
        count[root] += 1

    return [len(count), max(count.values()) if count else 0]
